//! Groups and SmartArt in tests/corpus/pptx/groups.pptx (generated by
//! scripts/corpus/gen_pptx_groups.py): selecting shapes inside groups,
//! moving and editing them, Group / Ungroup / Regroup, SmartArt text and
//! Convert to Shapes; saved and read back.

use std::collections::BTreeMap;
use std::io::{Cursor, Read as _};
use std::path::PathBuf;

use slides_engine::{
    Inner, Paint, Presentation, Rgb, Selection, ShapeKind, ShapeRef, Xfrm, text_ops,
};

fn corpus() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/corpus/pptx/groups.pptx")
}

fn parts(bytes: &[u8]) -> BTreeMap<String, Vec<u8>> {
    let mut zip = zip::ZipArchive::new(Cursor::new(bytes)).unwrap();
    let mut out = BTreeMap::new();
    for i in 0..zip.len() {
        let mut f = zip.by_index(i).unwrap();
        let name = f.name().unwrap().into_owned();
        let mut v = Vec::new();
        f.read_to_end(&mut v).unwrap();
        out.insert(name, v);
    }
    out
}

fn text(parts: &BTreeMap<String, Vec<u8>>, name: &str) -> String {
    String::from_utf8(parts[name].clone()).unwrap()
}

fn idx(p: &Presentation, slide: usize, name: &str) -> usize {
    p.slide(slide)
        .shapes
        .iter()
        .position(|s| s.name == name)
        .unwrap_or_else(|| panic!("no {name}"))
}

fn inner(slide: usize, top: usize, path: &[usize]) -> ShapeRef {
    ShapeRef(slide, top, Inner::of(path).unwrap())
}

fn close(a: Xfrm, b: Xfrm) {
    let d = |x: i64, y: i64| (x - y).abs() <= 2;
    assert!(
        d(a.x, b.x) && d(a.y, b.y) && d(a.cx, b.cx) && d(a.cy, b.cy) && a.rot == b.rot,
        "{a:?} != {b:?}"
    );
}

fn reopen(p: &mut Presentation) -> (Presentation, BTreeMap<String, Vec<u8>>) {
    let bytes = p.to_bytes().unwrap();
    (Presentation::from_bytes(bytes.clone()).unwrap(), parts(&bytes))
}

fn type_at_end(p: &mut Presentation, r: ShapeRef, s: &str) {
    let end = text_ops::end(p.text_paras(r).unwrap());
    p.insert_text(r, Selection::caret(end), s, None).unwrap();
}

#[test]
fn unchanged_save_is_byte_identical() {
    let mut p = Presentation::open(&corpus()).unwrap();
    let orig = parts(&std::fs::read(corpus()).unwrap());
    let (_, saved) = reopen(&mut p);
    for (k, v) in &orig {
        assert_eq!(&saved[k], v, "{k}");
    }
}

#[test]
fn shapes_inside_groups_are_placed_through_the_child_space() {
    let p = Presentation::open(&corpus()).unwrap();
    let scaled = idx(&p, 0, "Scaled");
    let g = p.slide(0).shapes[scaled].group().unwrap();
    assert_eq!(g.children.len(), 2);
    let gx = p.slide(0).shapes[scaled].xfrm.unwrap();
    assert_eq!(gx.cx, g.child_box.cx * 2);
    // The first child is drawn twice as wide as it is stored.
    let c = p.placed(inner(0, scaled, &[0])).unwrap();
    assert_eq!(c.xfrm.cx, g.children[0].xfrm.unwrap().cx * 2);
    assert_eq!(c.parent, Some((gx, g.child_box)));
    // Hit testing finds the child under a point, nested groups too.
    let outer = idx(&p, 0, "Outer");
    let dot_b = p.placed(inner(0, outer, &[1, 1])).unwrap().xfrm;
    let (x, y) = (dot_b.x + 10, dot_b.y + 10);
    assert_eq!(p.inner_at((0, outer), x, y), Some(inner(0, outer, &[1])));
    assert_eq!(
        p.inner_at(inner(0, outer, &[1]), x, y),
        Some(inner(0, outer, &[1, 1]))
    );
}

#[test]
fn moving_a_group_moves_its_children_and_saves_the_child_space() {
    let mut p = Presentation::open(&corpus()).unwrap();
    let pair = idx(&p, 0, "Pair");
    let before = p.placed(inner(0, pair, &[1])).unwrap().xfrm;
    let g0 = p.slide(0).shapes[pair].xfrm.unwrap();
    let space = p.slide(0).shapes[pair].group().unwrap().child_box;
    // Move right and make it twice as tall.
    let moved = Xfrm {
        x: g0.x + 914_400,
        cy: g0.cy * 2,
        ..g0
    };
    p.set_xfrm((0, pair), moved, false).unwrap();
    let after = p.placed(inner(0, pair, &[1])).unwrap().xfrm;
    assert_eq!(after.x - before.x, 914_400);
    assert_eq!(after.cy, before.cy * 2);
    // Turned: the children turn with it.
    p.set_xfrm((0, pair), moved.with_degrees(90.0), false).unwrap();
    assert_eq!(p.placed(inner(0, pair, &[0])).unwrap().xfrm.rot, 90 * 60_000);
    let (back, saved) = reopen(&mut p);
    let xml = text(&saved, "ppt/slides/slide1.xml");
    assert!(
        xml.contains(&format!(
            "<a:chOff x=\"{}\" y=\"{}\"/><a:chExt cx=\"{}\" cy=\"{}\"/>",
            space.x, space.y, space.cx, space.cy
        )),
        "{xml}"
    );
    assert_eq!(back.slide(0).shapes[pair].xfrm, Some(moved.with_degrees(90.0)));
    close(
        back.placed(inner(0, pair, &[0])).unwrap().xfrm,
        p.placed(inner(0, pair, &[0])).unwrap().xfrm,
    );
    // Undo puts it back.
    p.undo();
    p.undo();
    assert_eq!(p.slide(0).shapes[pair].xfrm, Some(g0));
}

#[test]
fn text_and_fill_of_shapes_inside_groups() {
    let mut p = Presentation::open(&corpus()).unwrap();
    let pair = idx(&p, 0, "Pair");
    let outer = idx(&p, 0, "Outer");
    let left = inner(0, pair, &[0]);
    type_at_end(&mut p, left, " side");
    assert_eq!(p.text_paras(left).unwrap()[0].text, "Left side");
    let dot = inner(0, outer, &[1, 0]);
    p.set_fill(dot, Paint::Rgb(Rgb([0x12, 0x34, 0x56]))).unwrap();
    let orig = parts(&std::fs::read(corpus()).unwrap());
    let (back, saved) = reopen(&mut p);
    assert_eq!(back.text_paras(left).unwrap()[0].text, "Left side");
    assert_eq!(back.shape(dot).unwrap().look.fill, Some(Rgb([0x12, 0x34, 0x56])));
    // Only the edited slide changed.
    for (k, v) in &orig {
        if k != "ppt/slides/slide1.xml" {
            assert_eq!(&saved[k], v, "{k}");
        }
    }
    // The groups' own XML (unchanged boxes) is kept.
    let xml = text(&saved, "ppt/slides/slide1.xml");
    let src = text(&orig, "ppt/slides/slide1.xml");
    let grp_sppr = |s: &str, name: &str| {
        let at = s.find(&format!("name=\"{name}\"")).unwrap();
        let a = s[at..].find("<p:grpSpPr").unwrap() + at;
        let b = s[a..].find("</p:grpSpPr>").unwrap() + a;
        s[a..b].to_owned()
    };
    assert_eq!(grp_sppr(&xml, "Pair"), grp_sppr(&src, "Pair"));
    assert_eq!(grp_sppr(&xml, "Inner"), grp_sppr(&src, "Inner"));
    p.undo();
    p.undo();
    assert_eq!(p.text_paras(left).unwrap()[0].text, "Left");
}

#[test]
fn moving_a_child_refits_the_group_and_keeps_the_others() {
    let mut p = Presentation::open(&corpus()).unwrap();
    let scaled = idx(&p, 0, "Scaled");
    let other = p.placed(inner(0, scaled, &[1])).unwrap().xfrm;
    let c = p.placed(inner(0, scaled, &[0])).unwrap().xfrm;
    let target = Xfrm {
        x: c.x - 914_400,
        y: c.y + 457_200,
        ..c
    };
    p.set_xfrm(inner(0, scaled, &[0]), target, false).unwrap();
    close(p.placed(inner(0, scaled, &[0])).unwrap().xfrm, target);
    close(p.placed(inner(0, scaled, &[1])).unwrap().xfrm, other);
    // The group's box now starts where the moved child does.
    let gx = p.slide(0).shapes[scaled].xfrm.unwrap();
    assert!((gx.x - target.x).abs() <= 2, "{gx:?} {target:?}");
    assert!(gx.y + gx.cy >= target.y + target.cy - 2);
    let (back, _) = reopen(&mut p);
    close(back.placed(inner(0, scaled, &[0])).unwrap().xfrm, target);
    close(back.placed(inner(0, scaled, &[1])).unwrap().xfrm, other);
}

#[test]
fn deleting_from_a_two_shape_group_ungroups_the_other() {
    let mut p = Presentation::open(&corpus()).unwrap();
    let pair = idx(&p, 0, "Pair");
    let n = p.slide(0).shapes.len();
    let right = p.placed(inner(0, pair, &[1])).unwrap().xfrm;
    p.delete_shape(inner(0, pair, &[0])).unwrap();
    assert_eq!(p.slide(0).shapes.len(), n);
    let s = &p.slide(0).shapes[pair];
    assert_eq!(s.name, "Right");
    assert!(!s.is_group());
    close(s.xfrm.unwrap(), right);
    // A nested group's leaf: the inner group dissolves into the outer one.
    let outer = idx(&p, 0, "Outer");
    p.delete_shape(inner(0, outer, &[1, 0])).unwrap();
    let g = p.slide(0).shapes[outer].group().unwrap();
    assert_eq!(g.children.len(), 2);
    assert_eq!(g.children[1].name, "Dot B");
    let (back, _) = reopen(&mut p);
    assert_eq!(back.slide(0).shapes[pair].name, "Right");
    assert_eq!(back.slide(0).shapes[outer].group().unwrap().children.len(), 2);
    p.undo();
    p.undo();
    assert!(p.slide(0).shapes[pair].is_group());
}

#[test]
fn group_ungroup_regroup_round_trip() {
    let mut p = Presentation::open(&corpus()).unwrap();
    let a = idx(&p, 0, "Loose A");
    let b = idx(&p, 0, "Loose B");
    let (xa, xb) = (
        p.slide(0).shapes[a].xfrm.unwrap(),
        p.slide(0).shapes[b].xfrm.unwrap(),
    );
    let n = p.slide(0).shapes.len();
    // Placeholders can't be grouped.
    let title = idx(&p, 0, "Title 1");
    assert!(p.group_shapes(0, &[title, a]).is_err());
    let g = p.group_shapes(0, &[a, b]).unwrap();
    assert_eq!(p.slide(0).shapes.len(), n - 1);
    let gs = &p.slide(0).shapes[g];
    assert!(gs.is_group());
    let gx = gs.xfrm.unwrap();
    assert_eq!((gx.x, gx.y), (xa.x, xa.y));
    assert_eq!(gx.x + gx.cx, xb.x + xb.cx);
    let ids: Vec<u32> = p.slide(0).shapes.iter().map(|s| s.id).collect();
    assert!(!ids[..g].contains(&gs.id));
    // Saved and read back as a group with the same children.
    let (back, saved) = reopen(&mut p);
    let bg = &back.slide(0).shapes[g];
    assert!(bg.is_group(), "{:?}", bg.kind);
    assert_eq!(bg.group().unwrap().children.len(), 2);
    close(back.placed(inner(0, g, &[1])).unwrap().xfrm, xb);
    let xml = text(&saved, "ppt/slides/slide1.xml");
    assert_eq!(xml.matches("<p:grpSp>").count(), 5, "{xml}");
    // Ungroup "Pair" (scaled children come out where they were drawn).
    let scaled = idx(&p, 0, "Scaled");
    let drawn: Vec<Xfrm> = (0..2)
        .map(|k| p.placed(inner(0, scaled, &[k])).unwrap().xfrm)
        .collect();
    let out = p.ungroup((0, scaled)).unwrap();
    assert_eq!(out.len(), 2);
    for (r, x) in out.iter().zip(&drawn) {
        close(p.slide(0).shapes[r.1].xfrm.unwrap(), *x);
    }
    assert!(p.can_regroup(0));
    let rg = p.regroup(0).unwrap();
    let rs = &p.slide(0).shapes[rg];
    assert_eq!(rs.name, "Scaled");
    for (k, x) in drawn.iter().enumerate() {
        close(p.placed(inner(0, rg, &[k])).unwrap().xfrm, *x);
    }
    let (back, _) = reopen(&mut p);
    let rs = &back.slide(0).shapes[rg];
    assert_eq!(rs.name, "Scaled");
    assert_eq!(rs.group().unwrap().children[0].name, "Wide 1");
    // Ungrouping a nested group inside a group.
    let outer = idx(&p, 0, "Outer");
    let r = p.ungroup(inner(0, outer, &[1])).unwrap();
    assert_eq!(r, [inner(0, outer, &[1]), inner(0, outer, &[2])]);
    assert_eq!(p.slide(0).shapes[outer].group().unwrap().children.len(), 3);
    // All of it undoes.
    for _ in 0..4 {
        p.undo();
    }
    assert_eq!(p.slide(0).shapes.len(), n);
    assert!(!p.can_undo());
}

#[test]
fn copying_a_group_gives_its_shapes_new_ids() {
    let mut p = Presentation::open(&corpus()).unwrap();
    let outer = idx(&p, 0, "Outer");
    let dup = p.duplicate_shape((0, outer)).unwrap();
    let mut ids = Vec::new();
    fn walk(s: &slides_engine::Shape, ids: &mut Vec<u32>) {
        ids.push(s.id);
        for c in s.group().map(|g| g.children.as_slice()).unwrap_or_default() {
            walk(c, ids);
        }
    }
    for s in &p.slide(0).shapes {
        walk(s, &mut ids);
    }
    let n = ids.len();
    ids.sort_unstable();
    ids.dedup();
    assert_eq!(ids.len(), n, "ids are unique");
    assert!(p.slide(0).shapes[dup].is_group());
}

fn smartart(p: &Presentation) -> usize {
    p.slide(1)
        .shapes
        .iter()
        .position(|s| s.smartart().is_some())
        .expect("SmartArt with its drawing")
}

#[test]
fn smartart_text_is_saved_to_the_drawing_and_the_data_model() {
    let mut p = Presentation::open(&corpus()).unwrap();
    let d = smartart(&p);
    assert_eq!(p.slide(1).shapes[d].smartart().unwrap().group.children.len(), 5);
    // SmartArt shapes can't be moved or deleted (that needs PowerPoint's layouts).
    let plan = inner(1, d, &[0]);
    let x = p.placed(plan).unwrap().xfrm;
    assert!(p.set_xfrm(plan, Xfrm { x: x.x + 10, ..x }, false).is_err());
    assert!(p.delete_shape(plan).is_err());
    type_at_end(&mut p, plan, " 2027");
    // The empty placeholder item gets text.
    type_at_end(&mut p, inner(1, d, &[1]), "Build");
    // A shape showing two items: each paragraph goes to its item, and
    // the paragraph count stays.
    let both = inner(1, d, &[4]);
    type_at_end(&mut p, both, "!");
    assert!(
        p.insert_text(both, Selection::caret(text_ops::end(p.text_paras(both).unwrap())), "\nThree", None)
            .is_err()
    );
    // Fill of a node goes on its presentation item too.
    p.set_fill(inner(1, d, &[2]), Paint::Rgb(Rgb([0xAA, 0x00, 0x11]))).unwrap();

    let orig = parts(&std::fs::read(corpus()).unwrap());
    let (back, saved) = reopen(&mut p);
    let drawing = text(&saved, "ppt/diagrams/drawing1.xml");
    let data = text(&saved, "ppt/diagrams/data1.xml");
    assert!(drawing.contains("<a:t>Plan 2027</a:t>"), "{drawing}");
    assert!(drawing.contains("<a:t>Build</a:t>"));
    assert!(drawing.contains("<a:t>Two!</a:t>"));
    assert!(drawing.contains("AA0011"));
    assert!(data.contains("<a:t>Plan 2027</a:t>"), "{data}");
    assert!(data.contains("<a:t>Build</a:t>"));
    assert!(!data.contains("phldr=\"1\""), "{data}");
    assert!(data.contains("<a:t>One</a:t>") && data.contains("<a:t>Two!</a:t>"));
    // The data model's text doesn't take the drawing's fitted sizes.
    assert!(!data.contains("sz=\"2400\""), "{data}");
    assert!(!data.contains("kern="), "{data}");
    // The fill is on the presentation item "B…3".
    let pres_pt = data
        .find("modelId=\"{B0000000-0000-0000-0000-000000000003}\"")
        .unwrap();
    assert!(data[pres_pt..].find("AA0011").unwrap() < data[pres_pt..].find("</dgm:pt>").unwrap());
    // Everything else is as it was (the slide part only re-zipped).
    for (k, v) in &orig {
        if !k.starts_with("ppt/diagrams/drawing1") && !k.starts_with("ppt/diagrams/data1") {
            assert_eq!(saved[k], *v, "{k}");
        }
    }
    let bd = smartart(&back);
    let g = &back.slide(1).shapes[bd].smartart().unwrap().group;
    assert_eq!(g.children[0].text.as_ref().unwrap().plain_text(), "Plan 2027");
    assert_eq!(g.children[4].text.as_ref().unwrap().plain_text(), "One\nTwo!");
    // Undo.
    for _ in 0..4 {
        p.undo();
    }
    assert_eq!(p.text_paras(plan).unwrap()[0].text, "Plan");
}

#[test]
fn smartart_converts_to_a_group_of_shapes() {
    let mut p = Presentation::open(&corpus()).unwrap();
    let d = smartart(&p);
    let placed: Vec<Xfrm> = (0..5)
        .map(|k| p.placed(inner(1, d, &[k])).unwrap().xfrm)
        .collect();
    type_at_end(&mut p, inner(1, d, &[0]), "!");
    let g = p.convert_to_shapes((1, d)).unwrap();
    let s = &p.slide(1).shapes[g];
    assert!(s.is_group());
    let kids = &s.group().unwrap().children;
    assert_eq!(kids.len(), 5);
    assert!(kids.iter().all(|k| matches!(k.kind, ShapeKind::Shape { .. })));
    assert_eq!(kids[0].text.as_ref().unwrap().plain_text(), "Plan!");
    for (k, x) in placed.iter().enumerate() {
        close(p.placed(inner(1, g, &[k])).unwrap().xfrm, *x);
    }
    // The text box's offset became the text insets.
    let ins = kids[0].text.as_ref().unwrap().body.insets;
    assert_eq!(ins, [Some(136_200); 4]);
    let (back, saved) = reopen(&mut p);
    let bs = &back.slide(1).shapes[g];
    assert_eq!(bs.group().unwrap().children.len(), 5);
    assert_eq!(
        bs.group().unwrap().children[4].text.as_ref().unwrap().plain_text(),
        "One\nTwo"
    );
    // The SmartArt parts and relationships are gone.
    assert!(!saved.keys().any(|k| k.starts_with("ppt/diagrams/")), "{:?}", saved.keys());
    let rels = text(&saved, "ppt/slides/_rels/slide2.xml.rels");
    assert!(!rels.contains("diagram"), "{rels}");
    assert!(!text(&saved, "[Content_Types].xml").contains("diagrams"));
    // Ids are unique on the slide.
    let mut ids: Vec<u32> = bs.group().unwrap().children.iter().map(|c| c.id).collect();
    ids.extend(back.slide(1).shapes.iter().map(|s| s.id));
    let n = ids.len();
    ids.sort_unstable();
    ids.dedup();
    assert_eq!(ids.len(), n);
    // Undo brings the SmartArt back; Ungroup on SmartArt converts it too.
    p.undo();
    assert!(p.slide(1).shapes[d].smartart().is_some());
    let r = p.ungroup((1, d)).unwrap();
    assert!(p.slide(1).shapes[r[0].1].is_group());
}
